def ways_to_stay_at_zero(steps,arrLen):
    mod=10**9+7;width=min(arrLen,steps//2+1);dp=[0]*width;dp[0]=1
    for _ in range(steps):
        nxt=[0]*width
        for i,count in enumerate(dp):
            for j in (i-1,i,i+1):
                if 0<=j<width:nxt[j]=(nxt[j]+count)%mod
        dp=nxt
    return dp[0]

